    def visiblePoints(self, points: List[List[int]], angle: int, location: List[int]) -> int:

        arr, extra = [], 0
        xx, yy = location

        for x, y in points:
            if x == xx and y == yy:
                extra += 1
                continue
            arr.append(math.atan2(y - yy, x - xx))

        arr.sort()
        arr = arr + [x + 2.0 * math.pi for x in arr]
        angle = math.pi * angle / 180

        l = ans = 0
        for r in range(len(arr)):
            while arr[r] - arr[l] > angle:
                l += 1
            ans = max(ans, r - l + 1)

        return ans + extra

class Solution:
    def minimumOneBitOperations(self, n: int) -> int:
        if n <= 1:
            return n
        def leftmostbit(x):
            x |= x >> 1
            x |= x >> 2
            x |= x >> 4
            x |= x >> 8
            x |= x >> 16
            x += 1
            x >>= 1
            return x
        x = leftmostbit(n)
        return ((x << 1) - 1) - self.minimumOneBitOperations(n - x)

