class Solution:
    def maximalNetworkRank(self, n: int, roads) -> int:
        degree = [0]*n
        adj = collections.defaultdict(set)
        for a, b in roads:
            degree[a] += 1
            degree[b] += 1
            adj[a].add(b)
            adj[b].add(a)
        result = 0
        for i in range(n-1):
            for j in range(i+1, n):
                result = max(result, degree[i]+degree[j]-int(i in adj and j in adj[i]))
        return result

class Solution:
    def checkPalindromeFormation(self, a: str, b: str) -> bool:
        def pal(x):
            return x == x[::-1]
        if pal(a) or pal(b): return True
        # either grow from inside to outside, or vice versa
        ina = len(a)-1
        inb = 0
        outa = 0
        outb = len(b)-1

        while a[ina] == b[inb]:
            ina -= 1
            inb += 1
            if ina <= inb:
                return True # short circuit found break point
        # jump into each string now!?
        # is a or b a palindrome in this portion from inb to ina
        if pal(a[inb:ina+1]) or pal(b[inb:ina+1]):
            return True # either one is breakpoint, so check remainder is palindrome

        while a[outa] == b[outb]:
            outa += 1
            outb -= 1
            if outa >= outb:
                return True
        if pal(a[outa:outb+1]) or pal(b[outa:outb+1]):
            return True # either one is breakpoint, so check remainder

        return False

class Solution:
    def checkPalindromeFormation(self, a: str, b: str) -> bool:
        def is_palindrome(s, i, j):
            while i < j:
                if s[i] != s[j]:
                    return False
                i += 1
                j -= 1
            return True

        def check(a, b):
            i, j = 0, len(b)-1
            while i < j:
                if a[i] != b[j]:
                    return is_palindrome(a, i, j) or is_palindrome(b, i, j)
                i += 1
                j -= 1
            return True

        return check(a, b) or check(b, a)

